/* 隔离 A_6F 楼层 + 飞过去 */
const FLOOR = 'A_6F';
ssp.objectsTool.setVisibleByFloor(FLOOR);
const target = ssp.objectsTool.getByUserDataProperty('floorName', FLOOR)[0];
if (target) {
  await ssp.cameraController.flyToObject(target);
  console.log(`isolated to ${FLOOR}`);
}

